const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && getComputedStyle(e).visibility !== 'hidden'; };
const label = b => (b.textContent.trim() || b.getAttribute('aria-label') || b.title || '').replace(/\s+/g, ' ').slice(0, 24);
const legal = b => !!b.closest('.table, .btn-group, .lf-list-row, [role="tablist"]') || b.hasAttribute('aria-pressed') || b.closest('.lf-seg, [data-segmented]');
const bad = [];
for (const b of document.querySelectorAll('.btn-outline-primary')) {
  if (!vis(b) || legal(b)) continue;
  bad.push('無框品牌色按鈕不在列內／分段控制：' + label(b));
}
for (const b of document.querySelectorAll('.btn-outline-danger')) {
  // 停用中的按鈕本身是凹槽底，看得出是按鈕
  if (!vis(b) || legal(b) || b.disabled) continue;
  const cs = getComputedStyle(b);
  if (parseFloat(cs.borderTopWidth) === 0 || cs.borderTopColor === 'rgba(0, 0, 0, 0)' || cs.borderTopColor === 'transparent') bad.push('列外的危險動作入口沒有可見邊框：' + label(b));
}
// 主要按鈕的範圍：每個視窗、表單、清單列（如初始設定的步驟列）與標了 data-primary-scope 的區塊各自至多一顆
const scopeOf = b => b.closest('.modal, form, .list-group-item, [data-primary-scope]') || document.body;
const counts = new Map();
for (const b of document.querySelectorAll('.btn-primary')) {
  if (!vis(b) || b.closest('.lf-sidebar, .lf-topbar, .lf-setup-bar')) continue;
  const s = scopeOf(b);
  counts.set(s, [...(counts.get(s) || []), label(b)]);
}
for (const [s, list] of counts) if (list.length > 1) bad.push((s === document.body ? '頁面本體' : s.matches('.modal') ? '視窗' : '區塊') + '有 ' + list.length + ' 顆實心主要按鈕：' + list.join('、'));
return bad.length ? bad.join('；') : null;

const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && getComputedStyle(e).visibility !== 'hidden'; };
const desc = e => e.tagName.toLowerCase() + (e.className && typeof e.className === 'string' ? '.' + e.className.trim().split(/\s+/).join('.') : '') + '「' + (e.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 20) + '」';
const INTER = 'button, input, select, textarea, label, summary, a, [data-bs-toggle], [role="button"]';
const bad = [];
const inView = (x, y) => x >= 0 && y >= 0 && x < window.innerWidth && y < window.innerHeight;
const firstText = td => { const w = document.createTreeWalker(td, NodeFilter.SHOW_TEXT); let n; while ((n = w.nextNode())) { if (n.nodeValue.trim()) return n; } return null; };
for (const tr of document.querySelectorAll('tr.lf-row-link')) {
  if (!vis(tr)) continue;
  const a = tr.querySelector('.lf-row-link__anchor');
  if (!a) continue;
  const url = a.href;
  for (const td of tr.children) {
    if (!vis(td)) continue;
    const pts = [];
    const r = td.getBoundingClientRect();
    pts.push(['格中心', r.left + r.width / 2, r.top + r.height / 2]);
    const tn = firstText(td);
    if (tn) { const rg = document.createRange(); rg.selectNodeContents(tn); const tr2 = rg.getBoundingClientRect(); if (tr2.width > 0) pts.push(['文字中心', tr2.left + tr2.width / 2, tr2.top + tr2.height / 2]); }
    for (const [what, x, y] of pts) {
      if (!inView(x, y)) continue;
      const el = document.elementFromPoint(x, y);
      // 命中點落在列之外（被捲動容器裁掉、疊在其他元素下）不是這列的點擊區問題
      if (!el || !tr.contains(el)) continue;
      const link = el.closest('a');
      if (link && link.href === url) continue;
      const inter = el.closest(INTER);
      if (inter && td.contains(inter)) continue;
      const tt = el.closest('[title]'); if (tt && tt !== td && !tt.matches('td, th') && td.contains(tt)) continue;
      bad.push('整列連結點不到（' + what + '）：' + desc(el));
    }
  }
}
for (const td of document.querySelectorAll('td.text-truncate')) {
  if (!vis(td) || td.scrollWidth <= td.clientWidth) continue;
  const full = (td.textContent || '').trim();
  const tn = firstText(td);
  if (!tn) continue;
  const rg = document.createRange(); rg.selectNodeContents(tn);
  const rr = rg.getBoundingClientRect();
  const x = Math.min(rr.left + rr.width / 2, td.getBoundingClientRect().right - 2), y = rr.top + rr.height / 2;
  if (!inView(x, y)) continue;
  let el = document.elementFromPoint(x, y), t = null;
  while (el) { if (el.title) { t = el.title; break; } if (el === td) break; el = el.parentElement; }
  if (t === null || t.trim() !== full) bad.push('截斷文字沒有完整提示：' + desc(td));
}
return bad.length ? bad.slice(0, 6).join('；') + (bad.length > 6 ? '…共 ' + bad.length + ' 項' : '') : null;
